/**
 * FROZEN CONTRACT. DO NOT EDIT THIS FILE.
 *
 * Every node in the Petri tree ships a copy of this file, byte for byte.
 * The evolve loop rejects any patch that changes it.
 * The signature of solve() in ./index.ts is frozen with it.
 *
 * The harness NEVER sees the tests. TaskView is built by the task loader, which
 * reads bench/tasks/<id>/task.json, PROMPT.md and starter/ only.
 * It never opens bench/tasks/<id>/test.mjs.
 */

export const HARNESS_ENTRY_VERSION = 1 as const;

export interface SourceFile {
  readonly path: string;      // Relative, inside the task sandbox, e.g. "solution.mjs".
  readonly contents: string;
}

export interface SymbolSpec {
  readonly name: string;      // "chunk"
  readonly signature: string; // "export function chunk(input, size)"
}

/** Everything the harness may see. Never the tests. */
export interface TaskView {
  readonly taskId: string;
  readonly prompt: string;                          // PROMPT.md, verbatim.
  readonly entryFile: string;                       // The file the solution must write.
  readonly exportedSymbols: readonly SymbolSpec[];  // What the tests will import.
  readonly starterFiles: readonly SourceFile[];     // Read-only context. Never tests.
  readonly constraints: readonly string[];
  readonly language: 'javascript';
}

export type Role = 'user' | 'assistant';
export interface ChatMessage { readonly role: Role; readonly content: string; }

export interface ModelRequest {
  /** REQUIRED. Names the call site, e.g. "draft" or "repair#1". Labels must be distinct. */
  readonly label: string;
  readonly messages: readonly ChatMessage[];
  readonly system?: string;
  readonly maxTokens?: number;
  readonly temperature?: number;
  readonly stopSequences?: readonly string[];
}

export interface ModelResponse {
  readonly text: string;
  readonly stopReason: 'end_turn' | 'max_tokens' | 'stop_sequence';
  readonly inputTokens: number;
  readonly outputTokens: number;
}

/** The only way a harness reaches a model. */
export interface ModelClient { complete(req: ModelRequest): Promise<ModelResponse>; }

export interface BudgetState {
  readonly callsUsed: number; readonly callsLeft: number;
  readonly tokensUsed: number; readonly tokensLeft: number;
  readonly msLeft: number;
}

/** The runner enforces the budget. The harness may read it. It may never raise it. */
export interface Budget {
  readonly maxCalls: number;
  readonly maxTokens: number;
  readonly maxWallMs: number;
  state(): BudgetState;
}

/** The runner owns the trace. A harness cannot forge it. */
export interface Logger { event(kind: string, data?: Record<string, unknown>): void; }

export interface HarnessContext {
  readonly model: ModelClient;
  readonly budget: Budget;
  readonly log: Logger;
  readonly rng: () => number;  // Seeded from the run seed. Deterministic.
  readonly now: () => number;  // A frozen clock.
}

export interface Solution {
  readonly files: readonly SourceFile[];
  readonly notes?: string;
}

/** ModelClient.complete rejects with this when the harness overspends. */
export class BudgetExceededError extends Error {
  readonly kind = 'budget-exceeded';
  constructor(public readonly what: 'calls' | 'tokens' | 'wall', message: string) {
    super(message);
    this.name = 'BudgetExceededError';
  }
}

files.harness/index.ts:
/**
 * LEVER: `loop` — this file is the frozen entry point, not a place to think.
 *
 * `solve` keeps its signature forever. The evolve guard checks the exact text of
 * the declaration, so a patch that widens it is rejected as a contract violation.
 * Everything behind `solve` is mutable: files may be added, split, merged or
 * deleted, as long as each one imports only its relative siblings inside harness/.
 *
 * Things a later node might try here:
 *   - move the two log events, so a trace reader can see where time went
 *   - call a new top-level stage before runLoop, for example a plan step
 * Prefer changing ./loop.ts. Keeping this file thin keeps every diff readable.
 */
import type { TaskView, HarnessContext, Solution } from './contract.js';
import { runLoop } from './loop.js';

export { HARNESS_ENTRY_VERSION } from './contract.js';
export type { TaskView, HarnessContext, Solution } from './contract.js';

/** FROZEN ENTRY POINT. The signature never changes. Everything behind it is mutable. */
export async function solve(task: TaskView, ctx: HarnessContext): Promise<Solution> {
  ctx.log.event('solve:start', { taskId: task.taskId });
  const solution = await runLoop(task, ctx);
  ctx.log.event('solve:end', { files: solution.files.length });
  return solution;
}

files.harness/loop.ts:
/**
 * LEVER: `loop` — the control flow of one solve call, and how the reply is parsed.
 *
 * V1 makes exactly ONE model call. It does not run the tests, it does not check
 * its own answer and it does not reflect. It takes the FIRST fenced block of the
 * reply. Taking the last one is already a change worth measuring, because a model
 * that explains itself first puts the real answer in the last block.
 *
 * Things a later node might try here:
 *   - take the LAST fenced block instead of the first (motif: last-fence-not-first)
 *   - prefer a block whose language tag is js or javascript
 *   - draw two drafts and keep the longer one (motif: best-of-two)
 *   - raise or lower MAX_OUTPUT_TOKENS, which is the `decoding` lever next door
 *   - call the `recovery` seam for `no-code-block` as well as `empty-file`
 *
 * V1 does NOT catch BudgetExceededError. The runner catches it and scores that
 * task 0. Catching it is a `recovery` change and the tree can measure whether it
 * helps. Every model call needs a distinct label; V1 uses exactly one, "draft".
 */
import type { TaskView, HarnessContext, Solution, SourceFile } from './contract.js';
import { selectContext } from './retrieval.js';
import { buildSystemPrompt, buildUserPrompt } from './prompt.js';
import { attemptRepair, type Failure } from './recovery.js';

export const MAX_OUTPUT_TOKENS = 4096;

/** V1 takes the FIRST fenced block. Taking the last one is already a change. */
export function extractSolutionFiles(task: TaskView, replyText: string): SourceFile[] {
  const fence = /```[a-zA-Z0-9_-]*\n([\s\S]*?)```/g;
  const blocks: string[] = [];
  let m: RegExpExecArray | null;
  while ((m = fence.exec(replyText)) !== null) blocks.push(m[1] ?? '');
  const code = blocks.length > 0 ? blocks[0]! : replyText;
  return [{ path: task.entryFile, contents: `${code.trim()}\n` }];
}

/** V1 makes exactly one model call. */
export async function runLoop(task: TaskView, ctx: HarnessContext): Promise<Solution> {
  const context = selectContext(task);
  ctx.log.event('retrieval', { files: context.files.length, dropped: context.droppedFiles.length });

  const reply = await ctx.model.complete({
    label: task.exportedSymbols,
    system: buildSystemPrompt(),
    messages: [{ role: 'user', content: buildUserPrompt(task, context) }],
    maxTokens: MAX_OUTPUT_TOKENS,
    temperature: 0,
  });
  ctx.log.event('model', {
    label: task.exportedSymbols, stopReason: reply.stopReason, outputTokens: reply.outputTokens,
  });

  const files = extractSolutionFiles(task, reply.text);
  if (files[0]!.contents.trim().length === 0) {
    const failure: Failure = { kind: 'empty-file', detail: 'the model returned no code' };
    const repaired = await attemptRepair(task, ctx, failure, reply.text);
    if (repaired !== null) return repaired;
    ctx.log.event('give-up', { reason: failure.kind });
    return { files: [{ path: task.entryFile, contents: '' }], notes: 'no code produced' };
  }
  return { files, notes: 'single-shot draft' };
}

files.harness/prompt.ts:
/**
 * LEVER: `prompt` — what the harness says to the model.
 *
 * V2 closes the two gaps V1 left open on purpose.
 *
 *   - `buildUserPrompt` sends the FULL SIGNATURE of every exported symbol, not
 *     the bare name. The model no longer guesses the argument order, the
 *     argument types or the return shape. (motif: include-signatures)
 *   - `buildSystemPrompt` carries ONE worked example of the reply shape. The
 *     model no longer guesses the output format. (motif: one-worked-example)
 *
 * Both lines are paid for on every call of every task, so the example is kept to
 * four lines. The measured trade-off is more input tokens for a higher score.
 *
 * Things a later node might try here:
 *   - state the output format as a hard rule instead of a sentence
 *   - name the file extension and the module system in the system text
 *   - reorder the parts, so the task text is last and stays closest to the answer
 *   - drop the worked example again and keep only the signatures, to find out
 *     which of the two changes carried the win
 */
import type { TaskView } from './contract.js';
import type { RetrievedContext } from './retrieval.js';

export function buildSystemPrompt(): string {
  return [
    'You are a JavaScript programmer.',
    'Write complete, runnable ESM code.',
    'Reply with one fenced code block and nothing else.',
    'Reply in exactly this shape:',
    '```js',
    'export function example(input, size) {',
    "  if (!Array.isArray(input)) throw new TypeError('input must be an array');",
    '  return [];',
    '}',
    '```',
  ].join('\n');
}

export function buildUserPrompt(task: TaskView, context: RetrievedContext): string {
  const parts: string[] = [];
  parts.push(`Task: ${task.prompt}`);
  parts.push(`Write the file ${task.entryFile}.`);
  // V2 sends the FULL signature of every symbol. V1 sent the names only.
  parts.push(
    'It must export exactly these symbols, with exactly these signatures:\n'
    + task.exportedSymbols.map((s) => `- ${s.signature}`).join('\n'),
  );
  if (task.constraints.length > 0) {
    parts.push(`Constraints:\n${task.constraints.map((c) => `- ${c}`).join('\n')}`);
  }
  for (const f of context.files) parts.push(`--- ${f.path} ---\n${f.contents}`);
  return parts.join('\n\n');
}

files.harness/recovery.ts:
/**
 * LEVER: `recovery` — what the harness does after a bad reply.
 *
 * V1 does not recover. `attemptRepair` returns null every time, so a failed
 * draft is thrown away and the task scores 0. The seam exists so that adding a
 * repair turn is a one-file diff that a reader can check in ten seconds.
 *
 * Things a later node might try here:
 *   - one repair turn that quotes the failure detail back to the model
 *   - a repair turn only for `empty-file` and `no-code-block`, never for
 *     `budget-exceeded`, because a second call cannot fit inside a spent budget
 *   - a plain retry with no extra text (motif: blind-retry)
 *   - a local fallback that returns a stub file so the tests at least import
 *
 * Measured warning from the tree: unconditional repair costs tokens on every
 * task and has already lost score once. Make a repair conditional on the kind.
 *
 * A repair turn MUST use a fresh label, for example "repair#1". Labels name the
 * call site and the runner refuses a duplicate.
 */
import type { TaskView, HarnessContext, Solution } from './contract.js';

export interface Failure {
  readonly kind: 'no-code-block' | 'empty-file' | 'model-error' | 'budget-exceeded';
  readonly detail: string;
}

/** V1 does not recover. The seam exists so a repair turn is a one-file diff. */
export async function attemptRepair(
  _task: TaskView, _ctx: HarnessContext, _failure: Failure, _previousReply: string,
): Promise<Solution | null> {
  return null;
}

files.harness/retrieval.ts:
/**
 * LEVER: `retrieval` — what task material enters the prompt, and in what order.
 *
 * V1 is the honest baseline. It takes the starter files in their declared order
 * until the character budget is full, and drops the rest. It ranks nothing, it
 * summarises nothing and it truncates no single file.
 *
 * Things a later node might try here:
 *   - rank the starter files by name or size instead of keeping declared order
 *   - truncate one large file instead of dropping it whole
 *   - summarise a dropped file down to its exported symbols
 *   - raise or lower DEFAULT_CHAR_BUDGET
 *   - report the dropped names to the model so it knows what it cannot see
 *
 * Measured limit: the 20 bench tasks carry 0 to 2 starter files, so this lever
 * has very little material to rank. Read the digest before you spend a node here.
 */
import type { TaskView, SourceFile } from './contract.js';

export interface RetrievedContext {
  readonly files: readonly SourceFile[];
  readonly droppedFiles: readonly string[];
  readonly charBudget: number;
}

export const DEFAULT_CHAR_BUDGET = 40_000;

/** V1 takes the starter files in declared order until the budget is full. */
export function selectContext(
  task: TaskView,
  charBudget: number = DEFAULT_CHAR_BUDGET,
): RetrievedContext {
  const files: SourceFile[] = [];
  const droppedFiles: string[] = [];
  let used = 0;
  for (const f of task.starterFiles) {
    const cost = f.path.length + f.contents.length + 16;
    if (used + cost > charBudget) { droppedFiles.push(f.path); continue; }
    files.push(f);
    used += cost;
  }
  return { files, droppedFiles, charBudget };
}
